+fn request_tools(raw: &Map<String, Value>) -> Result<Option<Vec<String>>, Unsupported> {
+    let choice = raw.get("tool_choice").filter(|c| !c.is_null());
+    if choice.is_some_and(|c| c != "auto" && c != "none")
